package com.tekwatt.ocpp.service;import com.fasterxml.jackson.databind.JsonNode;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;@Service public class FirmwareStatusNotifier{private final RestClient firmware;public FirmwareStatusNotifier(RestClient.Builder b,@Value("${tekwatt.firmware.service-url:http://localhost:8096}")String url){firmware=b.baseUrl(url).build();}public void notify(String station,JsonNode payload){String status=payload.path("status").asText();if(status.isBlank())return;try{firmware.post().uri("/api/v1/firmware/callbacks/status").body(Map.of("chargerId",UUID.fromString(station),"status",status,"statusInfo",status)).retrieve().toBodilessEntity();}catch(Exception ignored){}}}
